// BFF：把多个后端响应聚合成一个前端友好的 payload，减少前端往返
async function bffCart(userId, fetchers) {
  const [user, cart, recommendations] = await Promise.all([
    fetchers.user(userId),
    fetchers.cart(userId),
    fetchers.reco(userId),
  ]);
  return { profile: user, items: cart, suggest: recommendations };
}

const fakeFetchers = {
  user: (id) => Promise.resolve({ id, tier: "gold" }),
  cart: (id) => Promise.resolve([{ sku: "A", qty: 2 }]),
  reco: (id) => Promise.resolve(["B", "C"]),
};

bffCart("u1", fakeFetchers).then((r) =>
  console.log(JSON.stringify(r))
);
